import threading

from once import call_once, lazy_singleton


N_THREADS = 50


def _run_concurrently(callee, n=N_THREADS):
    """Release n threads simultaneously via a Barrier, collect their results."""
    barrier = threading.Barrier(n)
    results = [None] * n
    errors = []

    def worker(i):
        try:
            barrier.wait()  # everyone lines up here...
            results[i] = callee()  # ...then all released at once
        except BaseException as exc:  # pragma: no cover - surfaced below
            errors.append(exc)

    threads = [
        threading.Thread(target=worker, args=(i,), daemon=True) for i in range(n)
    ]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)

    assert not errors, f"worker threads raised: {errors!r}"
    return results


class TestCallOnce:
    def test_runs_exactly_once_under_contention(self):
        calls = []  # plain list append as the run counter

        def initializer():
            calls.append(1)
            return object()

        once = call_once(initializer)

        results = _run_concurrently(once)

        assert len(results) == N_THREADS
        assert len(calls) == 1, f"initializer ran {len(calls)} times"
        # Every thread observed the exact same object identity.
        assert all(r is results[0] for r in results)

    def test_sequential_repeats_return_same_object(self):
        calls = []
        obj = object()

        def initializer():
            calls.append(1)
            return obj

        once = call_once(initializer)
        assert once() is obj
        assert once() is obj
        assert once() is obj
        assert len(calls) == 1

    def test_exception_is_not_cached_next_call_retries(self):
        attempts = []
        sentinel = object()

        def flaky():
            attempts.append(1)
            if len(attempts) < 2:
                raise RuntimeError("boom")
            return sentinel

        once = call_once(flaky)

        try:
            once()
        except RuntimeError as exc:
            assert str(exc) == "boom"
        else:
            raise AssertionError("first call should have propagated the error")

        # Failure was not cached: retry happens and succeeds.
        assert once() is sentinel
        assert len(attempts) == 2
        # And now it's cached.
        assert once() is sentinel
        assert len(attempts) == 2

    def test_exception_under_full_contention_still_eventually_succeeds(self):
        lock = threading.Lock()
        attempts = []

        def flaky():
            with lock:
                attempts.append(1)
            raise RuntimeError("always fails")

        once = call_once(flaky)
        barrier = threading.Barrier(N_THREADS)
        caught = [0] * N_THREADS

        def worker(i):
            try:
                barrier.wait()
                once()
            except RuntimeError:
                caught[i] += 1

        threads = [
            threading.Thread(target=worker, args=(i,), daemon=True)
            for i in range(N_THREADS)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=30)

        assert all(c == 1 for c in caught), f"caught counts: {caught}"
        assert len(attempts) >= 1  # retried rather than caching the failure


class TestLazySingleton:
    def test_single_identity_across_racing_threads(self):
        constructions = []

        @lazy_singleton
        def singleton():
            constructions.append(1)
            return {"id": id(singleton)}

        results = _run_concurrently(singleton)

        assert len(constructions) == 1
        assert all(r is results[0] for r in results)

    def test_lazy_not_eager(self):
        ran = []

        @lazy_singleton
        def thing():
            ran.append(1)
            return object()

        import time

        time.sleep(0.05)  # give any (incorrectly) eager init a chance to show
        assert not ran
        thing()
        assert len(ran) == 1

    def test_retry_after_failure(self):
        state = {"n": 0}

        @lazy_singleton
        def flaky():
            state["n"] += 1
            if state["n"] == 1:
                raise ValueError("not yet")
            return ("ok", state["n"])

        try:
            flaky()
        except ValueError:
            pass
        else:
            raise AssertionError("expected first attempt to fail")

        assert flaky() == ("ok", 2)
        assert flaky() == ("ok", 2)

